import { NextResponse } from "next/server"
import dbConnect from "@/lib/db"
import Vendor from "@/models/Vendor"
import Order from "@/models/Order"
import MenuItem from "@/models/MenuItem"
import Landmark from "@/models/Landmark"
import SubLandmark from "@/models/SubLandmark"
import GlobalSettings from "@/models/GlobalSettings"
import { serializeOrder } from "@/lib/serializers"
import {
  ORDER_STATUS,
  generateOrderId,
  LOW_STOCK_THRESHOLD,
} from "@/lib/constants"
import { computeMonnifyServiceFee } from "@/lib/fees"
import { initMonnifyTransaction } from "@/lib/monnify"
import { sendOrderInitiatedEmail } from "@/lib/mail"
import { sendVendorLowStockAlertEmail } from "@/lib/vendorAlertMail"
import {
  resolveDeliveryFee,
  validateOrderItemsAndCalculateTotal,
} from "@/lib/services/orderCheckoutService"
import { createOrderSchema } from "@/lib/schemas"

export async function GET(request: Request) {
  try {
    await dbConnect()

    const { searchParams } = new URL(request.url)
    const orderId = searchParams.get("orderId")

    if (!orderId) {
      return NextResponse.json(
        { error: "orderId is required" },
        { status: 400 }
      )
    }

    const order = await Order.findOne({ orderId }).lean()

    if (!order) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 })
    }

    const serializedOrder = serializeOrder(order)
    return NextResponse.json(serializedOrder)
  } catch (error) {
    console.error("Error fetching order:", error)
    return NextResponse.json(
      { error: "Failed to fetch order" },
      { status: 500 }
    )
  }
}

// ── POST /api/orders

export async function POST(request: Request) {
  try {
    await dbConnect()

    const body = await request.json()

    // Validate request body using Zod
    const parsedBody = createOrderSchema.safeParse(body)
    if (!parsedBody.success) {
      return NextResponse.json(
        { error: "Invalid request data", details: parsedBody.error.format() },
        { status: 400 }
      )
    }

    const {
      vendorId,
      items,
      customerName,
      customerEmail,
      customerPhone,
      location,
      exactLocation,
      notes,
    } = parsedBody.data

    // Verify vendor exists and is active before accepting the order
    const vendor = await Vendor.findById(vendorId).lean()
    if (!vendor || !vendor.isActive) {
      return NextResponse.json(
        { error: "Vendor not found or inactive" },
        { status: 404 }
      )
    }

    // Securely source the vendor's WhatsApp number directly from the database (Source of Truth)
    const finalWhatsapp = vendor.whatsappNumber
    if (!finalWhatsapp) {
      return NextResponse.json(
        { error: "Vendor does not have a configured WhatsApp number" },
        { status: 400 }
      )
    }

    const finalVendorName = vendor.name

    // Server-side Price Calculation (Fixes Client-Side Pricing Trust Vulnerability)
    const deliveryFee = await resolveDeliveryFee(vendor, location)

    let calculatedTotal: number
    let maxHours: number
    let maxItemPrepTime: string
    let dbMenuItemsMap: Map<string, any>

    try {
      const validationResult = await validateOrderItemsAndCalculateTotal(
        items,
        vendorId,
        deliveryFee
      )
      calculatedTotal = validationResult.calculatedTotal
      maxHours = validationResult.maxHours
      maxItemPrepTime = validationResult.maxItemPrepTime
      dbMenuItemsMap = validationResult.dbMenuItemsMap
    } catch (validationError: any) {
      return NextResponse.json(
        { error: validationError.message || "Failed to validate order items" },
        { status: 400 }
      )
    }

    // Gross-up formula: collect exactly enough from the customer so that after Monnify
    // takes their 1.5% cut of the total, the vendor absorbs zero processing fee.
    // See lib/fees.ts for the full derivation.
    const serviceFee = computeMonnifyServiceFee(calculatedTotal)
    const finalTotal = calculatedTotal + serviceFee

    // Calculate exact revenue split
    const settings = await GlobalSettings.findOne()
    const platformFeePercentage = settings
      ? settings.platformFeePercentage
      : Number(process.env.NEXT_PUBLIC_PLATFORM_FEE_PERCENTAGE || 5)

    // Commission is calculated only on the vendor's items (food subtotal), NOT the delivery fee.
    // The vendor keeps 100% of the delivery fee.
    const foodSubtotal = calculatedTotal - deliveryFee
    const platformCommission = foodSubtotal * (platformFeePercentage / 100)
    const vendorRevenue = calculatedTotal - platformCommission

    // Generate a collision-resistant order ID first (needed for paymentReference + redirectUrl)
    const orderId = generateOrderId()
    const paymentReference = `BH-PAY-${orderId}`

    if (!vendor.monnifySubAccountCode) {
      return NextResponse.json(
        {
          error:
            "This vendor is not connected to Monnify. Cannot process payment.",
        },
        { status: 400 }
      )
    }

    const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://bitehubapp.com"
    const redirectUrl = `${appUrl}/order/${orderId}`

    // Use splitAmount (exact NGN) instead of splitPercentage.
    // vendorRevenue = calculatedTotal × (1 - platformFee%) — the vendor's clean share of
    // the base subtotal (food + delivery), before the service fee.
    //
    // Why splitAmount and NOT splitPercentage:
    //   - The customer pays a gross-up service fee on top of the base total.
    //   - That service fee is sized to exactly cover Monnify's 1.5% processing charge.
    //   - With splitPercentage, the service fee gets split 98/2 between vendor and platform,
    //     so the platform's 2% commission is nearly wiped out by Monnify's charge.
    //   - With splitAmount, the vendor receives exactly their base share. The remaining
    //     balance (service fee + platform commission) stays with the merchant contract, and
    //     Monnify deducts its fee from that remainder — leaving the platform with a clean
    //     net commission ≈ platformFee% × base.
    const vendorSplitAmount = Math.round(vendorRevenue * 100) / 100

    let checkoutUrl: string
    let transactionReference: string
    try {
      const monnifyInit = await initMonnifyTransaction({
        amount: finalTotal,
        paymentReference,
        customerName,
        customerEmail,
        paymentDescription: `BiteHub Order ${orderId} from ${finalVendorName}`,
        vendorSubAccountCode: vendor.monnifySubAccountCode,
        vendorSplitAmount,
        redirectUrl,
      })
      checkoutUrl = monnifyInit.checkoutUrl
      transactionReference = monnifyInit.transactionReference
    } catch (monnifyError: unknown) {
      const errMsg =
        monnifyError instanceof Error ? monnifyError.message : "Unknown error"
      console.error("[POST /api/orders] Monnify init failed:", errMsg)
      return NextResponse.json(
        { error: "Failed to initialize payment. Please try again." },
        { status: 502 }
      )
    }

    // Reserve quantity by decrementing immediately
    const bulkOps = items.map((item) => {
      const dbItem = dbMenuItemsMap.get(item.menuItemId)
      const updateDoc: {
        $inc: { quantityAvailable: number }
        $set?: { lowStockAlertSent: boolean }
      } = { $inc: { quantityAvailable: -item.quantity } }

      if (
        dbItem &&
        dbItem.quantityAvailable !== null &&
        dbItem.quantityAvailable !== undefined
      ) {
        const newQuantity = dbItem.quantityAvailable - item.quantity
        if (newQuantity <= LOW_STOCK_THRESHOLD && !dbItem.lowStockAlertSent) {
          updateDoc.$set = { lowStockAlertSent: true }
          // Fire-and-forget — alert must not block the checkout response
          sendVendorLowStockAlertEmail(
            vendorId,
            finalVendorName,
            dbItem.name,
            newQuantity
          ).catch((err) =>
            console.error("[POST /api/orders] Low stock alert failed:", err)
          )
        }
      }

      return {
        updateOne: {
          filter: { _id: item.menuItemId, quantityAvailable: { $ne: null } },
          update: updateDoc,
        },
      }
    })
    if (bulkOps.length > 0) {
      await MenuItem.bulkWrite(bulkOps).catch((err) => {
        console.error("[POST /api/orders] Failed to decrement quantity:", err)
      })
    }

    const order = await Order.create({
      orderId,
      vendorId,
      vendorName: finalVendorName,
      vendorWhatsappNumber: finalWhatsapp,
      vendorPrepTime: maxHours !== -1 ? maxItemPrepTime : vendor.prepTime || "",
      items,
      customerName,
      customerEmail,
      customerPhone,
      location: `${exactLocation} (${location})`,
      notes: notes || "",
      deliveryFee,
      serviceFee,
      platformCommission,
      vendorRevenue,
      totalAmount: finalTotal,
      status: ORDER_STATUS.PENDING,
      paymentMethod: "monnify",
      paymentStatus: "pending",
      monnifyReference: paymentReference,
      expiresAt: new Date(Date.now() + 30 * 60000), // 30 minutes from now
    })

    // Float the promise so it sends asynchronously without blocking the checkout redirect
    sendOrderInitiatedEmail(
      customerEmail,
      customerName,
      order.orderId,
      finalVendorName,
      finalTotal,
      redirectUrl
    ).catch(console.error)

    return NextResponse.json(
      { orderId: order.orderId, checkoutUrl, transactionReference },
      { status: 201 }
    )
  } catch (error) {
    console.error("[POST /api/orders] Error creating order:", error)
    return NextResponse.json(
      { error: "Failed to create order" },
      { status: 500 }
    )
  }
}

"use client"

import { useState, useEffect, useRef } from "react"
import { useParams } from "next/navigation"
import Link from "next/link"
import { Navbar } from "@/components/Navbar"
import { Footer } from "@/components/Footer"
import { OrderStatusTracker } from "@/components/cart/OrderStatusTracker"
import { WhatsAppButton } from "@/components/cart/WhatsAppButton"
import { OrderItemsBreakdown } from "@/components/cart/OrderItemsBreakdown"
import { OrderHeroCard } from "@/components/cart/OrderHeroCard"
import { EmptyState } from "@/components/shared/EmptyState"
import { FetchError } from "@/components/shared/FetchError"
import { PageSkeleton } from "@/components/shared/PageSkeleton"
import {
  Home,
  ShoppingBag,
  MessageCircle,
  ChevronRight,
  Clock,
  Loader2,
  AlertCircle,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { useOrder } from "@/hooks/queries/useOrder"
import {
  usePayOrder,
  useVerifyOrderPayment,
} from "@/hooks/mutations/usePublicMutations"
import { toast } from "sonner"
import {
  FeedbackModal,
  FEEDBACK_SNOOZE_DURATION,
} from "@/components/shared/FeedbackModal"
import { ORDER_STATUS } from "@/lib/constants"

export default function OrderPage() {
  const { orderId } = useParams<{ orderId: string }>()
  const [showFeedbackModal, setShowFeedbackModal] = useState(false)

  const { data: order, isLoading, isError, error, refetch } = useOrder(orderId)
  const [isRetryingPayment, setIsRetryingPayment] = useState(false)
  const [isVerifyingDirectly, setIsVerifyingDirectly] = useState(true)
  const [isStalePayment, setIsStalePayment] = useState(false)
  const hasVerified = useRef(false)

  const verifyPaymentMutation = useVerifyOrderPayment()

  // Immediately verify the source of truth with Monnify on page load
  useEffect(() => {
    if (order?.paymentStatus === "pending" && !hasVerified.current) {
      hasVerified.current = true
      // Verification is already in progress (isVerifyingDirectly initialized to true)
      verifyPaymentMutation.mutate(orderId, {
        onSuccess: (data: any) => {
          if (data.success) {
            // It was actually paid! Update the UI immediately.
            refetch()
          } else {
            // It's genuinely pending/cancelled/failed at Monnify.
            // Since they are on this tracking page, it means they dropped off.
            setIsStalePayment(true)
          }
        },
        onError: (err: unknown) => {
          console.error("Failed to verify transaction status directly:", err)
          // Fallback if API fails: show the retry button anyway so they aren't stuck
          setIsStalePayment(true)
        },
        onSettled: () => {
          setIsVerifyingDirectly(false)
        },
      })
    }
  }, [order?.paymentStatus, orderId, refetch, verifyPaymentMutation])

  const payOrderMutation = usePayOrder()

  const handlePaymentRetry = () => {
    if (!order) return
    setIsRetryingPayment(true)
    payOrderMutation.mutate(order.orderId, {
      onSuccess: (data: any) => {
        if (data.checkoutUrl) {
          toast.success("Redirecting to secure payment...")
          window.location.href = data.checkoutUrl
        } else {
          toast.error("Missing checkout URL")
        }
      },
      onError: (err: unknown) => {
        console.error(err)
        const errMsg =
          err instanceof Error
            ? err.message
            : "Failed to initiate payment retry. Please contact support."
        toast.error(errMsg)
      },
      onSettled: () => {
        setIsRetryingPayment(false)
      },
    })
  }

  useEffect(() => {
    if (order?.status === ORDER_STATUS.COMPLETED) {
      const handled = localStorage.getItem(`feedback_handled_${orderId}`)
      const snoozedAt = localStorage.getItem(`feedback_snoozed_${orderId}`)

      const now = new Date().getTime()
      const isSnoozed =
        snoozedAt && now - parseInt(snoozedAt) < FEEDBACK_SNOOZE_DURATION

      if (!handled && !isSnoozed) {
        setTimeout(() => setShowFeedbackModal(true), 0)
      }
    }
  }, [order?.status, orderId])

  const handleRefresh = async () => {
    await refetch()
  }

  if (isLoading) {
    return (
      <main className="min-h-screen bg-background text-foreground">
        <Navbar />
        <div className="container mx-auto px-6 py-12">
          <PageSkeleton variant="order-detail" />
        </div>
        <Footer />
      </main>
    )
  }

  if (isError || !order) {
    const isNotFound =
      (error as { response?: { status?: number } })?.response?.status === 404

    if (isNotFound) {
      return (
        <main className="min-h-screen bg-background text-foreground">
          <Navbar />
          <div className="relative mx-auto max-w-2xl px-4 pt-6">
            <div className="flex items-center justify-between pb-2">
              <Button variant="outline" size="sm" asChild>
                <Link href="/order">
                  <ShoppingBag className="mr-2 size-4" />
                  Back to order track
                </Link>
              </Button>
              <Button variant="outline" size="sm" asChild>
                <Link href="/">
                  <Home className="mr-2 size-4" />
                  Back to home
                </Link>
              </Button>
            </div>
          </div>
          <EmptyState
            title="Order not found"
            description={`We couldn't find an order with ID "${orderId}". Please check the ID or try again later.`}
            action={{
              label: "Back to order",
              href: "/order",
              icon: <ShoppingBag className="size-4" />,
            }}
            className="py-40"
          />
          <Footer />
        </main>
      )
    }

    return (
      <main className="min-h-screen bg-background text-foreground">
        <Navbar />
        <FetchError
          title="Failed to load order"
          message="We encountered an issue while retrieving your order details."
          onRetry={handleRefresh}
          onBack="/"
          className="py-20"
        />
        <Footer />
      </main>
    )
  }

  return (
    <main className="min-h-screen bg-background pb-24 text-foreground">
      <Navbar />

      {/* Ambient background glow */}
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -top-40 left-1/2 h-[500px] w-[700px] -translate-x-1/2 rounded-full bg-primary/5 blur-[120px]" />
        <div className="absolute right-0 bottom-0 h-[300px] w-[400px] rounded-full bg-primary/3 blur-[100px]" />
      </div>

      <div className="relative mx-auto max-w-2xl space-y-4 px-4 py-10 sm:px-6 sm:py-14">
        {/* ── Back links ─────────────────────────────────────── */}
        <div className="flex items-center justify-between pb-2">
          <Button variant="outline" size="sm" asChild>
            <Link href="/order">
              <ShoppingBag className="mr-2 size-4" />
              Back to order track
            </Link>
          </Button>
          <Button variant="outline" size="sm" asChild>
            <Link href="/">
              <Home className="mr-2 size-4" />
              Back to home
            </Link>
          </Button>
        </div>

        <OrderHeroCard order={order} />

        {/* ── Payment verification banner ─────────────────────────── */}
        {order.paymentStatus === "pending" &&
          (!isStalePayment || isVerifyingDirectly) && (
            <div className="flex items-center gap-3 rounded-[20px] border border-amber-500/20 bg-amber-500/10 px-5 py-4">
              <Loader2 className="size-4 shrink-0 animate-spin text-amber-600" />
              <div>
                <p className="text-sm font-semibold text-amber-700 dark:text-amber-400">
                  Verifying your payment…
                </p>
                <p className="text-xs text-amber-600/80 dark:text-amber-500/80">
                  Contacting Monnify securely to confirm your transaction
                  status.
                </p>
              </div>
            </div>
          )}

        {/* ── Payment recovery banner ─────────────────────────────── */}
        {order.paymentStatus === "pending" &&
          isStalePayment &&
          !isVerifyingDirectly && (
            <div className="flex flex-col items-start justify-between gap-4 rounded-[20px] border border-destructive/20 bg-destructive/5 px-5 py-4 sm:flex-row sm:items-center">
              <div className="flex items-start gap-3 sm:items-center">
                <AlertCircle className="mt-0.5 size-5 shrink-0 text-destructive sm:mt-0" />
                <div>
                  <p className="text-sm font-semibold text-destructive">
                    Payment Incomplete
                  </p>
                  <p className="mt-0.5 text-xs text-destructive/80">
                    It looks like your payment wasn&apos;t completed. Please try
                    again to confirm your order.
                  </p>
                </div>
              </div>
              <Button
                onClick={handlePaymentRetry}
                disabled={isRetryingPayment}
                className="w-full shrink-0 bg-destructive text-white hover:bg-destructive/90 sm:w-auto"
              >
                {isRetryingPayment ? (
                  <>
                    <Loader2 className="mr-2 size-4 animate-spin" />
                    Please wait...
                  </>
                ) : (
                  "Complete Payment"
                )}
              </Button>
            </div>
          )}

        {/* ── Order status tracker ───────────────────────────────── */}
        <div className="rounded-[28px] border border-border bg-card p-7 shadow-sm sm:p-8">
          <div className="mb-6 flex items-center justify-between">
            <div className="flex items-center gap-2.5">
              <div className="flex size-8 items-center justify-center rounded-xl bg-primary/10">
                <ChevronRight className="size-4 text-primary" />
              </div>
              <h2 className="font-heading text-base font-bold sm:text-lg">
                Order status
              </h2>
            </div>
          </div>

          {order.vendorPrepTime && (
            <div className="mb-6 flex items-center gap-2 rounded-xl bg-primary/10 px-4 py-3 text-sm text-primary">
              <Clock className="size-4 animate-pulse" />
              <span className="font-medium">
                Estimated prep time: {order.vendorPrepTime}
              </span>
            </div>
          )}

          <OrderStatusTracker
            status={order.status}
            paymentStatus={order.paymentStatus}
          />
        </div>

        <OrderItemsBreakdown order={order} />

        {/* ── Contact vendor via WhatsApp ────────────────────────── */}
        <div className="rounded-[28px] border border-border bg-card shadow-sm">
          <div className="flex items-center gap-2.5 border-b border-border/60 px-7 py-5 sm:px-8">
            <div className="flex size-8 items-center justify-center rounded-xl bg-primary/10">
              <MessageCircle className="size-4 text-primary" />
            </div>
            <h2 className="font-heading text-base font-bold sm:text-lg">
              Contact vendor
            </h2>
          </div>

          <div className="px-7 py-5 sm:px-8">
            <p className="mb-4 text-sm leading-relaxed text-muted-foreground">
              Message the vendor on WhatsApp for any updates or questions about
              your order.
            </p>
            <WhatsAppButton
              vendorPhone={order.vendorWhatsappNumber}
              status={order.status}
              order={{
                orderId: order.orderId,
                customerName: order.customerName,
                items: order.items,
                total: order.totalAmount,
                notes: order.notes ?? undefined,
                paymentMethod: order.paymentMethod,
                paymentStatus: order.paymentStatus,
              }}
            />
          </div>
        </div>

        {/* ── Feedback Modal for completed orders ────────────────── */}
        {order && (
          <FeedbackModal
            open={showFeedbackModal}
            onOpenChange={setShowFeedbackModal}
            orderId={orderId}
            vendorName={order.vendorName}
            vendorId={order.vendorId}
          />
        )}
      </div>
    </main>
  )
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { ShoppingBag, X, Loader2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { useCart } from "@/hooks/useCart"
import { orderFormInputSchema, type OrderFormInputValues } from "@/lib/schemas"
import { normaliseNigerianPhone } from "@/lib/schemas"
import { zodResolver } from "@hookform/resolvers/zod"
import { useForm, Controller, type Resolver } from "react-hook-form"
import { Field, FieldError } from "@/components/ui/field"
import { toast } from "sonner"
import { formatPrice, formatPriceExact } from "@/lib/format"
import { computeMonnifyServiceFee } from "@/lib/fees"
import apiClient from "@/lib/axios"
import { AxiosError } from "axios"
import { useCreateOrder } from "@/hooks/mutations/usePublicMutations"
import { OrderFormCartItems } from "@/components/cart/OrderFormCartItems"
import { CustomerDetailsFields } from "@/components/cart/CustomerDetailsFields"

import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

interface DeliveryZone {
  id: string
  name: string
  fee: number
  subLandmarks: { id: string; name: string; fee: number }[]
}

interface OrderFormProps {
  open: boolean
  onClose: () => void
}

export function OrderForm({ open, onClose }: OrderFormProps) {
  const { cart, clearCart, syncVendorDetails, total } = useCart()
  const router = useRouter()
  const [loading, setLoading] = useState(false)
  const [isSyncing, setIsSyncing] = useState(false)
  const [serverError, setServerError] = useState<string | null>(null)
  const [deliveryZones, setDeliveryZones] = useState<DeliveryZone[]>([])

  const form = useForm<OrderFormInputValues>({
    resolver: zodResolver(
      orderFormInputSchema as never
    ) as unknown as Resolver<OrderFormInputValues>,
    defaultValues: {
      name: "",
      email: "",
      phone: "",
      location: "",
      exactLocation: "",
      notes: "",
      paymentMethod: "monnify",
    },
  })

  useEffect(() => {
    const saved = localStorage.getItem("bitehub_customer")
    if (saved) {
      try {
        const parsed = JSON.parse(saved)
        form.reset({ ...form.getValues(), ...parsed, notes: "" })
      } catch (e) {}
    }
  }, [form])

  // Local storage handles email loading now

  useEffect(() => {
    if (open && cart.vendorId) {
      setTimeout(() => {
        setIsSyncing(true)
      }, 0)
      apiClient
        .get(`/vendors/fee/${cart.vendorId}`)
        .then((res) => {
          if (res.data) {
            // We set fee to 0 initially to force location selection
            syncVendorDetails(
              cart.vendorId!,
              0,
              res.data.prepTime,
              res.data.monnifySubaccountCode
            )
          }
        })
        .catch((err) =>
          console.error("Failed to sync latest vendor details", err)
        )
        .finally(() => {
          setIsSyncing(false)
        })

      apiClient
        .get(`/vendors/${cart.vendorId}/delivery-zones`)
        .then((res) => setDeliveryZones(res.data))
        .catch((err) => console.error("Failed to fetch delivery zones", err))
    }
  }, [open, cart.vendorId, syncVendorDetails])

  const selectedLocation = form.watch("location")

  // Auto-resolve fee when deliveryZones or selectedLocation changes (fixes localStorage restore bug)
  useEffect(() => {
    if (deliveryZones.length > 0 && selectedLocation && cart.vendorId) {
      let fee = 0
      deliveryZones.forEach((z) => {
        if (z.name === selectedLocation) fee = z.fee
        z.subLandmarks.forEach((s) => {
          if (`${z.name} - ${s.name}` === selectedLocation) fee = s.fee
        })
      })

      // Only update if it's different from current to prevent infinite loops
      if (cart.vendorDeliveryFee !== fee) {
        syncVendorDetails(cart.vendorId, fee)
      }
    }
  }, [
    deliveryZones,
    selectedLocation,
    cart.vendorId,
    cart.vendorDeliveryFee,
    syncVendorDetails,
  ])

  // Close the form automatically if the last item is removed
  useEffect(() => {
    if (open && cart.items.length === 0) {
      onClose()
    }
  }, [cart.items.length, open, onClose])

  // Gross-up formula: collect exactly enough from the customer so Monnify's 1.5% cut
  // of the total equals serviceFee. Vendor absorbs zero processing cost.
  // See lib/fees.ts for the full derivation.
  const serviceFee = computeMonnifyServiceFee(total)
  const finalTotal = total + serviceFee

  if (!open) return null

  const createOrderMutation = useCreateOrder()

  const onSubmit = (values: OrderFormInputValues) => {
    setServerError(null)

    if (cart.items.length === 0 || !cart.vendorId) return

    const customerPhone = normaliseNigerianPhone(values.phone)

    setLoading(true)
    if (typeof window !== "undefined") {
      localStorage.setItem(
        "bitehub_customer",
        JSON.stringify({
          name: values.name,
          email: values.email,
          phone: values.phone,
          location: values.location,
          exactLocation: values.exactLocation,
        })
      )
    }

    createOrderMutation.mutate(
      {
        vendorId: cart.vendorId,
        vendorName: cart.vendorName,
        vendorWhatsappNumber: cart.vendorWhatsappNumber || "",
        items: cart.items.map((ci) => ({
          menuItemId: ci.menuItem.id,
          name: ci.menuItem.name,
          price: ci.menuItem.price,
          quantity: ci.quantity,
        })),
        customerName: values.name,
        customerEmail: values.email,
        customerPhone,
        location: values.location,
        exactLocation: values.exactLocation,
        notes: values.notes,
        paymentMethod: "monnify",
        total: finalTotal,
      },
      {
        onSuccess: (data: any) => {
          const { checkoutUrl } = data

          toast.success("Redirecting to secure payment...")
          onClose()
          clearCart()
          window.location.href = checkoutUrl
        },
        onError: (error: unknown) => {
          const apiError =
            error instanceof AxiosError
              ? error.response?.data?.error
              : "Something went wrong placing your order. Please try again."
          setServerError(apiError)
        },
        onSettled: () => {
          setLoading(false)
        },
      }
    )
  }

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
      />

      <div className="relative max-h-[90vh] w-full overflow-y-auto rounded-t-3xl border border-border bg-card shadow-2xl sm:max-w-lg sm:rounded-3xl">
        {/* Header */}
        <div className="sticky top-0 z-10 flex items-center justify-between rounded-t-3xl border-b border-border bg-card px-6 py-4">
          <div>
            <p className="text-xs text-muted-foreground">{cart.vendorName}</p>
            <h2 className="font-heading text-lg font-bold">Place your order</h2>
          </div>
          <Button
            variant="ghost"
            size="icon"
            onClick={onClose}
            disabled={loading}
          >
            <X />
          </Button>
        </div>

        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 p-6">
          <OrderFormCartItems loading={loading} />

          {/* Fees Breakdown */}
          <div className="space-y-2 rounded-2xl bg-muted/30 p-4 text-sm">
            <div className="flex justify-between text-muted-foreground">
              <span>Items Subtotal</span>
              <span>
                {formatPrice(
                  cart.items.reduce(
                    (sum, ci) => sum + ci.menuItem.price * ci.quantity,
                    0
                  )
                )}
              </span>
            </div>
            <div className="flex justify-between text-muted-foreground">
              <span>Delivery Fee</span>
              <span>
                {cart.vendorDeliveryFee > 0
                  ? formatPriceExact(cart.vendorDeliveryFee)
                  : "Select location"}
              </span>
            </div>
            <div className="flex justify-between text-muted-foreground">
              <span>Service Fee</span>
              <span>{formatPriceExact(serviceFee)}</span>
            </div>
            <div className="flex justify-between border-t border-border pt-2 font-bold">
              <span>Total to Pay</span>
              <span>{formatPriceExact(finalTotal)}</span>
            </div>
          </div>

          <CustomerDetailsFields
            control={form.control}
            deliveryZones={deliveryZones}
          />

          {/* Server error */}
          {serverError && (
            <p className="rounded-xl bg-destructive/10 px-4 py-2 text-center text-sm text-destructive">
              {serverError}
            </p>
          )}

          <Button
            type="submit"
            variant="hero"
            size="xl"
            className="w-full"
            disabled={
              loading ||
              isSyncing ||
              cart.items.length === 0 ||
              !selectedLocation
            }
          >
            {loading || isSyncing ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <ShoppingBag className="size-4" />
            )}
            {loading ? "Processing…" : `Pay ${formatPriceExact(finalTotal)}`}
          </Button>
        </form>
      </div>
    </div>
  )
}

